<script setup lang="ts">
import { onShow } from '@dcloudio/uni-app'
import { ref } from 'vue'
import { request } from '../../api/client'
import { type Property, type PropertyLead } from '../../api/properties'
import { hasRole } from '../../auth/session'
const tab = ref<'leads'|'properties'>('leads')
const leads = ref<PropertyLead[]>([])
const properties = ref<Property[]>([])
const loading = ref(false)
const load = async () => { loading.value = true; try { [leads.value, properties.value] = await Promise.all([request<PropertyLead[]>('/v1/property-leads'), request<Property[]>('/v1/properties')]) } catch (error) { uni.showToast({ title:error instanceof Error?error.message:'加载失败', icon:'none' }) } finally { loading.value = false } }
onShow(() => { if (!hasRole('admin')) { uni.redirectTo({ url:'/pages/admin/login' }); return } load() })
const convert = async (lead: PropertyLead) => { try { await request('/v1/property-leads/convert', { method:'POST', data:{ leadId:lead.id, title:lead.community, community:lead.community, location:lead.location, layout:lead.layout, rentMonthly:lead.expectedRentMonthly, description:lead.note, ownerId:'xiaopi-admin' } }); uni.showToast({ title:'已转为正式房源' }); load() } catch(error) { uni.showToast({ title:error instanceof Error?error.message:'转换失败', icon:'none' }) } }
const changeStatus = async (property: Property, status: string) => { try { await request('/v1/properties/status', { method:'PATCH', data:{ propertyId:property.id, status, operatorId:'xiaopi-admin' } }); uni.showToast({ title:'状态已更新' }); load() } catch(error) { uni.showToast({ title:error instanceof Error?error.message:'状态更新失败', icon:'none' }) } }
const contactLead = (phoneNumber: string) => uni.makePhoneCall({ phoneNumber })
</script>
<template><view class="page"><view class="work-head"><view><view class="title">小皮工作台</view><view class="muted">房源和客户线索统一管理</view></view><view class="refresh" @click="load">刷新</view></view><view class="tabs"><text :class="{active:tab==='leads'}" @click="tab='leads'">房源线索 {{ leads.length }}</text><text :class="{active:tab==='properties'}" @click="tab='properties'">正式房源 {{ properties.length }}</text></view><view v-if="loading" class="muted empty">加载中...</view><template v-else-if="tab==='leads'"><view v-for="lead in leads" :key="lead.id" class="card item"><view class="row"><view class="title small">{{ lead.community }}</view><text class="status">{{ lead.status }}</text></view><view class="muted">{{ lead.sourceName || '未填写姓名' }} · {{ lead.sourcePhone }}</view><view class="muted">{{ lead.location }} · {{ lead.layout }} · {{ lead.expectedRentMonthly }} 元/月</view><view class="note">{{ lead.note || '暂无补充说明' }}</view><view class="actions"><button @click="contactLead(lead.sourcePhone)">联系客户</button><button class="primary" @click="convert(lead)">转为正式房源</button></view></view><view v-if="!leads.length" class="empty muted">暂无房源线索</view></template><template v-else><view v-for="property in properties" :key="property.id" class="card item"><view class="row"><view class="title small">{{ property.title || property.community }}</view><text class="status">{{ property.status }}</text></view><view class="muted">{{ property.community }} · {{ property.layout }} · {{ property.location }}</view><view class="price">{{ property.rentMonthly }} 元/月</view><view class="actions"><button @click="changeStatus(property,'published')">发布</button><button @click="changeStatus(property,'offline')">下架</button><button class="primary" @click="changeStatus(property,'rented')">已出租</button></view></view><view v-if="!properties.length" class="empty muted">暂无正式房源</view></template></view></template>
<style scoped>.work-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:30rpx}.refresh{color:#0e8177;background:#e1f7f1;padding:12rpx 22rpx;border-radius:999rpx}.tabs{display:flex;background:#e3f6f1;border-radius:999rpx;padding:6rpx;margin-bottom:24rpx}.tabs text{flex:1;text-align:center;padding:18rpx;color:#5d938b}.tabs .active{background:#fff;border-radius:999rpx;color:#0e8177;font-weight:700}.small{font-size:34rpx}.item{padding:30rpx}.row{display:flex;justify-content:space-between;align-items:center}.status{background:#e8f8f3;color:#0e8177;padding:8rpx 14rpx;border-radius:999rpx;font-size:22rpx}.note{margin-top:18rpx;padding:18rpx;background:#f6fbf9;color:#57857e;border-radius:16rpx}.actions{display:flex;gap:14rpx;margin-top:24rpx}.actions button{flex:1;margin:0;background:#eff8f5;color:#0e8177;border-radius:999rpx;font-size:24rpx}.actions .primary{background:#0e8177;color:#fff}.empty{text-align:center;padding:100rpx 0}</style>
